html {
  scroll-behavior: smooth;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
  background-color: var(--bg-dark);
  color: var(--text-primary);
  line-height: 1.6;
  min-height: 100vh;
  padding: 2rem 1rem;
}

main {
  max-width: 700px;
  margin: 0 auto;
}

.quiz-container {
  background-color: var(--bg-card);
  border-radius: 12px;
  padding: 2.5rem;
  box-shadow: 0 10px 40px rgba(0, 0, 0, 0.3);
}

.quiz-header {
  margin-bottom: 2rem;
  text-align: center;
  border-bottom: 2px solid var(--primary);
  padding-bottom: 1.5rem;
}

h1 {
  font-size: 2rem;
  margin-bottom: 0.5rem;
  color: var(--primary);
}

.quiz-subtitle {
  color: var(--text-secondary);
  font-size: 1rem;
}

.form-field {
  margin-bottom: 2rem;
}

fieldset {
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 1.5rem;
  background-color: rgba(99, 102, 241, 0.03);
}

legend {
  font-size: 1.1rem;
  font-weight: 600;
  color: var(--text-primary);
  padding: 0 0.5rem;
  margin-bottom: 1rem;
}

.help-text {
  font-size: 0.9rem;
  color: var(--text-secondary);
  margin-bottom: 1rem;
  line-height: 1.5;
}

.checkbox-wrapper {
  display: flex;
  align-items: flex-start;
  margin-bottom: 1rem;
  gap: 0.75rem;
}

input[type="checkbox"] {
  width: 20px;
  height: 20px;
  min-width: 20px;
  min-height: 20px;
  margin-top: 0.2rem;
  cursor: pointer;
  accent-color: var(--primary);
}

input[type="checkbox"]:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
  border-radius: 2px;
}

label {
  cursor: pointer;
  font-size: 1rem;
  color: var(--text-primary);
  user-select: none;
}

label:hover {
  color: var(--primary);
}

.error-text {
  color: var(--error);
  font-size: 0.9rem;
  margin-top: 0.75rem;
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.error-text::before {
  content: "⚠ ";
}

.submit-btn {
  width: 100%;
  padding: 0.875rem 1.5rem;
  font-size: 1rem;
  font-weight: 600;
  background-color: var(--primary);
  color: white;
  border: none;
  border-radius: 8px;
  cursor: pointer;
  transition: all 0.2s ease;
  margin-top: 1.5rem;
}

.submit-btn:hover {
  background-color: var(--primary-dark);
  transform: translateY(-2px);
  box-shadow: 0 5px 15px rgba(99, 102, 241, 0.4);
}

.submit-btn:active {
  transform: translateY(0);
}

.submit-btn:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

.results-container {
  margin-top: 2rem;
  padding: 1.5rem;
  background-color: rgba(134, 239, 172, 0.1);
  border-left: 4px solid var(--success);
  border-radius: 8px;
  animation: slideIn 0.3s ease;
}

.results-container h2 {
  color: var(--success);
  margin-bottom: 0.75rem;
}

#resultsMessage {
  color: var(--text-primary);
  font-size: 1rem;
  line-height: 1.6;
}

@keyframes slideIn {
  from {
    opacity: 0;
    transform: translateY(-10px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@media (max-width: 640px) {
  .quiz-container {
    padding: 1.5rem;
  }

  h1 {
    font-size: 1.5rem;
  }

  legend {
    font-size: 1rem;
  }

  fieldset {
    padding: 1rem;
  }
}

@media (prefers-reduced-motion: reduce) {
  * {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}
