// Correct answers
const correctAnswers = {
  q1: ['python', 'javascript'], // Dynamically typed
  q2: ['scala', 'kotlin'],       // Run on JVM
  q3: ['cpp', 'csharp']          // Compiled languages
};

quizForm.addEventListener('submit', function(e) {
  e.preventDefault();

  // Clear previous errors
  document.querySelectorAll('.error-text').forEach(el => el.hidden = true);

  // Get user answers
  const userAnswers = {
    q1: Array.from(document.querySelectorAll('input[name="q1"]:checked')).map(el => el.value),
    q2: Array.from(document.querySelectorAll('input[name="q2"]:checked')).map(el => el.value),
    q3: Array.from(document.querySelectorAll('input[name="q3"]:checked')).map(el => el.value)
  };

  // Validate that at least one answer is selected for each question
  let isValid = true;
  let firstInvalidFieldset = null;

  Object.keys(userAnswers).forEach(questionKey => {
    if (userAnswers[questionKey].length === 0) {
      isValid = false;
      const errorElement = document.getElementById(questionKey + '-error');
      errorElement.textContent = 'Please select at least one answer.';
      errorElement.hidden = false;

      if (!firstInvalidFieldset) {
        firstInvalidFieldset = errorElement.closest('fieldset');
      }
    }
  });

  if (!isValid) {
    // Focus on the first invalid fieldset's legend
    if (firstInvalidFieldset) {
      firstInvalidFieldset.focus();
      firstInvalidFieldset.scrollIntoView({ behavior: 'smooth', block: 'center' });
    }
    return;
  }

  // Calculate score
  let score = 0;
  let totalQuestions = 3;
  const feedback = [];

  // Question 1 check
  const q1Correct = arraysEqual(userAnswers.q1.sort(), correctAnswers.q1.sort());
  if (q1Correct) {
    score++;
    feedback.push('✓ <strong>Question 1:</strong> Correct! Python and JavaScript are dynamically typed.');
  } else {
    feedback.push('✗ <strong>Question 1:</strong> Incorrect. The correct answers are Python and JavaScript.');
  }

  // Question 2 check
  const q2Correct = arraysEqual(userAnswers.q2.sort(), correctAnswers.q2.sort());
  if (q2Correct) {
    score++;
    feedback.push('✓ <strong>Question 2:</strong> Correct! Scala and Kotlin run on the JVM.');
  } else {
    feedback.push('✗ <strong>Question 2:</strong> Incorrect. The correct answers are Scala and Kotlin.');
  }

  // Question 3 check
  const q3Correct = arraysEqual(userAnswers.q3.sort(), correctAnswers.q3.sort());
  if (q3Correct) {
    score++;
    feedback.push('✓ <strong>Question 3:</strong> Correct! C++ and C# are compiled languages.');
  } else {
    feedback.push('✗ <strong>Question 3:</strong> Incorrect. The correct answers are C++ and C#.');
  }

  // Show results
  resultsMessage.innerHTML = `
    <p style="margin-bottom: 1rem;"><strong>Your Score: ${score}/${totalQuestions}</strong></p>
    ${feedback.map(f => `<p style="margin-bottom: 0.5rem;">${f}</p>`).join('')}
  `;
  resultsContainer.hidden = false;
  resultsContainer.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
});

